{
  "name": "Xspress3.10 X射线探测系统",
  "name_en": "Xspress3.10 X-ray Detector System",
  "manufacturer": "Quantum Detectors",
  "description": "Xspress3.10 是用于 X 射线荧光与多通道能谱采集的探测系统接口，可配置触发模式、管理 ROI、进行时间序列采集，并控制数据文件保存。",
  "description_en": "Xspress3.10 is an interface to an X-ray fluorescence and multichannel spectroscopy detector system, supporting trigger configuration, ROI management, time-series acquisition, and data file capture.",
  "actions": [
    {
      "action_name": "auto-restore_rois",
      "description": "从 ROI 文件恢复 ROI 设置。",
      "description_en": "Restore ROI settings from an ROI file."
    },
    {
      "action_name": "auto-roi_calib_info",
      "description": "获取 ROI 校准信息。",
      "description_en": "Get ROI calibration information."
    },
    {
      "action_name": "auto-select_rois_to_save",
      "description": "选择要保存的 ROI。",
      "description_en": "Select ROIs to save."
    },
    {
      "action_name": "auto-filePut",
      "description": "写入文件相关参数或数据。",
      "description_en": "Write file-related parameters or data."
    },
    {
      "action_name": "auto-fileGet",
      "description": "读取文件相关参数或数据。",
      "description_en": "Read file-related parameters or data."
    },
    {
      "action_name": "auto-setFilePath",
      "description": "设置文件保存路径。",
      "description_en": "Set the file save path."
    },
    {
      "action_name": "auto-setFileTemplate",
      "description": "设置文件名模板。",
      "description_en": "Set the file naming template."
    },
    {
      "action_name": "auto-setFileWriteMode",
      "description": "设置文件写入模式。",
      "description_en": "Set the file write mode."
    },
    {
      "action_name": "auto-setFileName",
      "description": "设置文件名。",
      "description_en": "Set the file name."
    },
    {
      "action_name": "auto-nextFileNumber",
      "description": "将文件编号递增到下一个值。",
      "description_en": "Increment the file number to the next value."
    },
    {
      "action_name": "auto-setFileNumber",
      "description": "设置文件编号。",
      "description_en": "Set the file number."
    },
    {
      "action_name": "auto-getLastFileName",
      "description": "获取最近生成的文件名。",
      "description_en": "Get the last generated file name."
    },
    {
      "action_name": "auto-FileCaptureOn",
      "description": "开启文件采集/写盘。",
      "description_en": "Enable file capture/writing."
    },
    {
      "action_name": "auto-FileCaptureOff",
      "description": "关闭文件采集/写盘。",
      "description_en": "Disable file capture/writing."
    },
    {
      "action_name": "auto-setFileNumCapture",
      "description": "设置要采集保存的文件帧数或数量。",
      "description_en": "Set the number of frames or items to capture to file."
    },
    {
      "action_name": "auto-FileWriteComplete",
      "description": "检查文件写入是否完成。",
      "description_en": "Check whether file writing is complete."
    },
    {
      "action_name": "auto-getFileTemplate",
      "description": "获取文件名模板。",
      "description_en": "Get the file naming template."
    },
    {
      "action_name": "auto-getFileName",
      "description": "获取文件名。",
      "description_en": "Get the file name."
    },
    {
      "action_name": "auto-getFileNumber",
      "description": "获取文件编号。",
      "description_en": "Get the file number."
    },
    {
      "action_name": "auto-getFilePath",
      "description": "获取文件保存路径。",
      "description_en": "Get the file save path."
    },
    {
      "action_name": "auto-getFileNameByIndex",
      "description": "按索引获取文件名。",
      "description_en": "Get a file name by index."
    },
    {
      "action_name": "auto-useExternalTrigger",
      "description": "切换为外部触发模式。",
      "description_en": "Switch to external trigger mode."
    },
    {
      "action_name": "auto-useInternalTrigger",
      "description": "切换为内部触发模式。",
      "description_en": "Switch to internal trigger mode."
    },
    {
      "action_name": "auto-setTriggerMode",
      "description": "设置触发模式。",
      "description_en": "Set the trigger mode."
    },
    {
      "action_name": "auto-get_rois",
      "description": "获取当前 ROI 列表或设置。",
      "description_en": "Get the current ROI list or settings."
    },
    {
      "action_name": "auto-TimeSeriesCaptureOn",
      "description": "开启时间序列采集。",
      "description_en": "Enable time-series capture."
    },
    {
      "action_name": "auto-TimeSeriesCaptureOff",
      "description": "关闭时间序列采集。",
      "description_en": "Disable time-series capture."
    }
  ],
  "tag_hints": [
    "X-ray fluorescence",
    "XRF spectroscopy",
    "multichannel analyzer",
    "ROI configuration",
    "trigger control",
    "time-series acquisition",
    "EPICS areaDetector",
    "data file capture"
  ]
}

